/// Evidence and its provenance are one transaction: a failed save leaves no
/// empty quotation behind, and never reports a quotation without its source.
pub fn create_with_data(
    conn: &Connection,
    input: &CreateStudyBlock,
    data: Option<&str>,
) -> AppResult<StudyBlock> {
    let content = input.content.as_deref().unwrap_or(

);
    validate::block_content(content)?;
    let section = sections::get(conn, &input.section_id)?;
    let field_key = input.field_key.as_deref().filter(|k| !k.is_empty());
    if let Some(key) = field_key {
        let known = section
            .fields
            .as_ref()
            .is_some_and(|f| f.fields.iter().any(|field| field.key == key));
        if !known {
            return Err(AppError::InvalidInput(crate::error::UserMessage::new(

,
            )));
        }
    }
    let qa_text;
    let mut content = content;
    if let Some(data) = data {
        if field_key.is_none() {
            // A.4.4 (#27): a free question block may be a paired question and answer.
            qa_text = qa_content(input.block_type, data)?;
            content = &qa_text;
        } else {
            validated_data(data)?;
        }
    }
    let tx = conn.unchecked_transaction()?;
    let position: i64 = tx.query_row(

,
        [&section.id],
        |row| row.get(0),
    )?;
    let now = now();
    let id = insert_answer(
        &tx,
        &section.id,
        input.block_type,
        position,
        content,
        field_key,
        data,
        &now,
    )?;
    studies::touch(&tx, &section.study_id, &now)?;
    let block = get(&tx, &id)?;
    tx.commit()?;
    Ok(block)
}

pub fn update(conn: &Connection, input: &UpdateStudyBlock) -> AppResult<StudyBlock> {
    let current = get(conn, &input.id)?;
    if input.content.is_none() && input.data.is_none() {
        return Ok(current);
    }
    let mut content = input
        .content
        .clone()
        .unwrap_or_else(|| current.content.clone());
    validate::block_content(&content)?;
    if let Some(data) = &input.data {
        if current.field_key.is_none() {
            // A.4.4 (#27): the question and answer are kept apart in data; the
            // text (for search, export and older builds) is derived from them.
            content = qa_content(current.block_type, data)?;
        } else {
            validated_data(data)?;
        }
    }
    let content = &content;
    let data = input.data.as_ref().or(current.data.as_ref());
    let now = now();
    conn.execute(

,
        params![input.id, content, data, now],
    )?;
    touch_study_of_section(conn, &current.section_id, &now)?;
    get(conn, &input.id)
}

