    Ok(value.trim().to_string())
}

fn long_text(value: &str) -> AppResult<String> {
    if value.chars().count() > BLOCK_MAX_CHARS {
        return Err(invalid(

,
        ));
    }
    Ok(value.to_string())
}

fn reference(value: &str) -> AppResult<String> {
