/// File names in the order a person reads them:

.
fn natural_key(name: &str) -> Vec<(String, u64)> {
    let mut out = Vec::new();
    let mut text = String::new();
    let mut number: Option<u64> = None;
    for c in name.to_lowercase().chars() {
        if let Some(d) = c.to_digit(10) {
            number = Some(
                number
                    .unwrap_or(0)
                    .saturating_mul(10)
                    .saturating_add(u64::from(d)),
            );
        } else {
            if let Some(n) = number.take() {
                out.push((std::mem::take(&mut text), n));
            }
            text.push(c);
        }
    }
    out.push((text, number.unwrap_or(0)));
    out
}

/// Reads documents as a Bible (v0.23): each through the library's adapter,
/// then all of them for books, chapters and verses. Nothing is kept yet.
pub fn stage_documents(paths: &[PathBuf], origin: ImportOrigin) -> AppResult<StagedImport> {
    if paths.len() > documents::MAX_FILES {
        return Err(AppError::Import(UserMessage::new(

,
        )));
    }
    let mut ordered: Vec<PathBuf> = paths.to_vec();
    ordered.sort_by_key(|p| natural_key(&file_name(p)));
    let mut total = 0u64;
    let mut files = Vec::with_capacity(ordered.len());
    for (index, path) in ordered.iter().enumerate() {
        total += fs::metadata(path)
            .map_err(|e| AppError::filesystem(path, e))?
            .len();
        if total > documents::MAX_TOTAL_BYTES {
            return Err(AppError::Import(UserMessage::new(

,
            )));
        }
        files.push(documents::read(path, index as u16)?);
    }
    let formats: BTreeSet<&str> = files.iter().map(|f| f.format).collect();
    if formats.len() > 1 {
        return Err(AppError::InvalidInput(UserMessage::new(

,
        )));
    }
    let format = files[0].format;
    // The language the documents state (EPUB, PDF metadata), never guessed from the text.
    let stated: BTreeSet<String> = files
        .iter()
        .filter_map(|f| f.metadata.language.as_deref())
        .filter_map(crate::scripture::language::normalise_tag)
        .collect();
    let language = (stated.len() == 1)
        .then(|| stated.into_iter().next())
        .flatten();
    let mut stage = DocumentStage {
        files,
        language: language.clone(),
        corrections: structure::Corrections::default(),
        origins: BTreeMap::new(),
        books: Vec::new(),
        left_out: Vec::new(),
        stats: structure::Stats::default(),
        unverified: BTreeMap::new(),
        apparatus: Vec::new(),
        saved: Vec::new(),
        matched: Vec::new(),
    };
    let content = recognise(&mut stage);
    let name = stage
        .files
        .iter()
        .find_map(|f| f.metadata.title.clone())
        .unwrap_or_else(|| suggested_name(&ordered));
    log::info!(

,
        stage.files.len(),
        format,
        content.books.len(),
        content.verse_count(),
        content.issues.len()
    );
    Ok(StagedImport {
        id: uuid::Uuid::new_v4().to_string(),
        origin,
        files: ordered,
        format,
        content,
        suggested_name: name,
        language_tag: language,
        documents: Some(stage),
    })
}

/// Reads the stage's documents for their verses, with its corrections.
fn recognise(stage: &mut DocumentStage) -> StagedContent {
    let units = stage.units();
    let found = structure::recognise(&units, stage.language.as_deref(), &stage.corrections);
    stage.origins = found.origins;
    stage.books = found.books;
    stage.left_out = found.left_out;
    stage.stats = found.stats;
    stage.unverified = found.unverified;
    stage.apparatus = found.apparatus;
    let mut content = found.content;
    // PDF pages whose text could not be read (or only in part): their verses
    // are missing, never guessed; the review says which pages.
    for file in &stage.files {
        if file.failed_pages.is_empty() {
            continue;
        }
        let pages = file
            .failed_pages
            .iter()
            .map(u32::to_string)
            .collect::<Vec<_>>()
            .join(

, pages.as_str()),
        );
    }
    content
}

impl StagedImport {
    /// Applies corrections kept from before (v0.24.3): each is matched to a
    /// heading found now, by its document, its wording and its place (and,
    /// when the document changed, by its wording alone if that is found only
    /// once); the documents are then read again with them. `earlier`: they
    /// were made when the same documents were added as another Bible. None
    /// is dropped: a correction that fits nothing is reported.
    pub fn apply_saved(&mut self, saved: Vec<SavedCorrection>, earlier: bool) -> AppResult<()> {
        let Some(stage) = self.documents.as_mut() else {
            return Ok(());
        };
        if saved.is_empty() {
            return Ok(());
        }
        let mut corrections = stage.corrections.clone();
        let mut states = Vec::new();
        for correction in saved {
            let same_file = stage
                .files
                .get(usize::from(correction.document_position))
                .is_some_and(|f| f.hash == correction.document_sha256);
            let in_document = |b: &&structure::FoundBook| {
                b.place.document == correction.document_position && b.heading == correction.heading
            };
            let exact =
                stage.books.iter().filter(in_document).find(|b| {
                    b.place.page == correction.page && b.place.segment == correction.segment
                });
            let found = match exact {
                Some(b) if same_file => Some(b),
                _ => {
                    let candidates: Vec<&structure::FoundBook> =
                        stage.books.iter().filter(in_document).collect();
                    match (exact, candidates.as_slice()) {
                        (Some(b), _) => Some(b),
                        (None, [one]) => Some(*one),
                        _ => None,
                    }
                }
            };
            let chosen = match correction.chosen_book.as_deref() {
                Some(code) => match canon::by_code(code) {
                    Some(book) => Some(book),
                    // A book this version does not know: shown, not applied.
                    None => {
                        states.push(SavedState {
                            heading: correction.heading.clone(),
                            page: correction.page,
                            chosen: correction.chosen_book.clone(),
                            detected_now: None,
                            index: None,
                            status:

,
                            correction,
                        });
                        continue;
                    }
                },
                None => None,
            };
            let state = match found {
                Some(book) => {
                    if !earlier && !correction.id.is_empty() {
                        stage.matched.push(correction.id.clone());
                    }
                    corrections.books.insert(book.index, chosen);
                    let status = if !same_file {

,
                    correction,
                },
            };
            states.push(state);
        }
        stage.corrections = corrections;
        stage.saved = states;
        self.content = recognise(stage);
        Ok(())
    }

    /// Reads the documents again with the person's corrections (v0.23):
    /// for each found book (by index), another book or none.
    pub fn correct(&mut self, books: &[(usize, Option<String>)]) -> AppResult<()> {
        let Some(stage) = self.documents.as_mut() else {
            return Err(AppError::InvalidInput(UserMessage::new(

,
            )));
        };
        let mut corrections = structure::Corrections::default();
        for (index, code) in books {
            if *index >= stage.books.len() {
                continue;
            }
            let book = match code {
                Some(code) => Some(canon::by_code(code).ok_or_else(|| {
                    AppError::InvalidInput(UserMessage::new(

,
                    ))
                })?),
                None => None,
            };
            corrections.books.insert(*index, book);
        }
        // A kept correction the review no longer sends because the
        // recogniser now reads the heading as the person chose stays in force
        // (it is the person's, should the reading change again); one the
        // person has changed is theirs to keep as changed.
        for state in &stage.saved {
            let Some(i) = state.index else { continue };
            let detected = stage
                .books
                .get(i)
                .and_then(|b| b.detected)
                .map(str::to_string);
            if !corrections.books.contains_key(&i)
                && state.chosen.is_some()
                && state.chosen == detected
            {
                corrections
                    .books
                    .insert(i, state.chosen.as_deref().and_then(canon::by_code));
            }
        }
        stage.saved.retain(|s| {
            s.index.is_none_or(|i| {
                corrections
                    .books
                    .get(&i)
                    .map(|b| b.map(|b| b.code.to_string()))
                    == Some(s.chosen.clone())
            })
        });
        stage.corrections = corrections;
        self.content = recognise(stage);
        Ok(())
    }
}

