impl<'p> ContextTracker<'p> {
    pub fn new(recogniser: &'p Recogniser, sectioned: bool) -> Self {
        Self {
            recogniser,
            sectioned,
            path: None,
            page: None,
            heading: OuterContext::default(),
            document: OuterContext::default(),
            recent: None,
            local: None,
            suspended: Vec::new(),
