    /// Whether a unit is the first line of running text on its PDF page
    /// (after the running head, if any).
    fn page_top(&self, unit: usize) -> bool {
        let Some(page) = self.units[unit].place.page else {
            return false;
        };
        let mut j = unit;
        while j > 0 {
            j -= 1;
            let u = &self.units[j];
            if u.place.page != Some(page) {
                return true;
            }
            if !u.edge {
                return false;
            }
        }
        true
    }

